interface Anime {
  id: number;
  title: string;
  episodes: number;
}

// index.ts
import fetch from 'node-fetch';

async function getAnimes(): Promise<Anime[]> {
  const response = await fetch('https://api.myanimelist.net/v2/anime?limit=50', {
    headers: {
      'X-MAL-CLIENT-ID': 'myclientid'
    }
  });

  const data = await response.json();

